import{_ as t,o as s,c as n,a8 as e}from"./chunks/framework.CAT8sTE0.js";const g=JSON.parse('{"title":"JVM 入门","description":"","frontmatter":{},"headers":[],"relativePath":"service/java/java-jvm.md","filePath":"service/java/java-jvm.md"}'),i={name:"service/java/java-jvm.md"};function p(d,a,l,o,r,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="jvm-入门" tabindex="-1">JVM 入门 <a class="header-anchor" href="#jvm-入门" aria-label="Permalink to &quot;JVM 入门&quot;">​</a></h1><blockquote><p><strong>优先级：P0（面试必考）</strong> — JVM 与并发并称 Java 面试两大护城河，几乎必问。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>JS 开发者不需要关心 V8 内存细节也能干活；但 Java 面试会把 JVM 内存模型、GC、类加载当基础题问。本文聚焦面试考点，不深入源码。</p></div><h2 id="jvm-是什么" tabindex="-1">JVM 是什么 <a class="header-anchor" href="#jvm-是什么" aria-label="Permalink to &quot;JVM 是什么&quot;">​</a></h2><p>Java 程序运行在 JVM（Java Virtual Machine）上：<code>.java</code> 编译为 <code>.class</code> 字节码，JVM 解释/编译执行。<strong>一次编译，到处运行</strong> 靠的就是 JVM 屏蔽了操作系统差异。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.java --javac--&gt; .class --JVM--&gt; 机器码</span></span></code></pre></div><h2 id="内存分区-必考-画图题" tabindex="-1">内存分区（必考，画图题） <a class="header-anchor" href="#内存分区-必考-画图题" aria-label="Permalink to &quot;内存分区（必考，画图题）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ 线程共享                              │</span></span>
<span class="line"><span>│  ┌──────────┬──────────┬──────────┐  │</span></span>
<span class="line"><span>│  │  堆 Heap  │ 方法区/元空间 │  直接内存 │  │</span></span>
<span class="line"><span>│  │ (对象实例) │ (类信息/常量) │ (NIO)    │  │</span></span>
<span class="line"><span>│  └──────────┴──────────┴──────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│ 线程私有                              │</span></span>
<span class="line"><span>│  ┌──────────┬──────────┬──────────┐  │</span></span>
<span class="line"><span>│  │ 虚拟机栈    │ 本地方法栈 │ 程序计数器 │  │</span></span>
<span class="line"><span>│  │ (方法调用) │ (native) │ (下一条指令)│  │</span></span>
<span class="line"><span>│  └──────────┴──────────┴──────────┘  │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>区域</th><th>存什么</th><th>线程</th><th>异常</th></tr></thead><tbody><tr><td><strong>堆</strong></td><td>所有对象实例、数组</td><td>共享</td><td><code>OutOfMemoryError: Java heap space</code></td></tr><tr><td><strong>方法区/元空间</strong></td><td>类信息、常量、静态变量（JDK 8+ 用元空间，本地内存）</td><td>共享</td><td><code>OOM: Metaspace</code></td></tr><tr><td><strong>虚拟机栈</strong></td><td>每个方法一个栈帧（局部变量、操作数栈）</td><td>私有</td><td><code>StackOverflowError</code>（递归过深）</td></tr><tr><td><strong>程序计数器</strong></td><td>当前执行指令地址</td><td>私有</td><td>无</td></tr><tr><td><strong>直接内存</strong></td><td>NIO 的堆外内存</td><td>共享</td><td><code>OOM: Direct buffer memory</code></td></tr></tbody></table><p><strong>JDK 8 变化</strong>：永久代（PermGen）→ 元空间（Metaspace），从堆内移到了本地内存，不再有 PermGen OOM。</p><h2 id="jit-jvm-为什么比解释执行快" tabindex="-1">JIT：JVM 为什么比解释执行快 <a class="header-anchor" href="#jit-jvm-为什么比解释执行快" aria-label="Permalink to &quot;JIT：JVM 为什么比解释执行快&quot;">​</a></h2><p><code>.class</code> 字节码不是机器码，JVM 有两种执行方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释执行：逐行翻译字节码 → 启动快，跑得慢</span></span>
<span class="line"><span>JIT 编译（Just-In-Time）：把&quot;热点代码&quot;整段编译成机器码 → 启动稍慢，跑得飞快</span></span></code></pre></div><p><strong>分层编译</strong>（面试常考）：方法先解释执行，调用够频繁后升级为 C1（快速编译）→ 继续热 → C2（深度优化编译，榨干性能）。</p><h3 id="逃逸分析-jit-的杀手锏优化" tabindex="-1">逃逸分析：JIT 的杀手锏优化 <a class="header-anchor" href="#逃逸分析-jit-的杀手锏优化" aria-label="Permalink to &quot;逃逸分析：JIT 的杀手锏优化&quot;">​</a></h3><p>JIT 分析对象的作用域，如果发现一个对象<strong>不会逃出方法外</strong>（没有 return、没被别的线程拿到），就做激进优化：</p><table tabindex="0"><thead><tr><th>优化</th><th>做什么</th></tr></thead><tbody><tr><td><strong>栈上分配</strong></td><td>对象直接在栈上创建，方法结束自动回收，<strong>不经过 GC</strong></td></tr><tr><td><strong>标量替换</strong></td><td>对象拆成一个个字段用局部变量存，连&quot;对象&quot;都不存在了</td></tr><tr><td><strong>锁消除</strong></td><td>发现同步锁的对象其实是线程私有的，锁直接删掉</td></tr></tbody></table><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 这个 User 对象没人拿到方法外 —— JIT 可能把它优化成&quot;栈上三个局部变量&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> handle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User u </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 逃逸分析：u 没逃逸 → 栈上分配，零 GC 压力</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    System.out.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>前端对照</strong>：JS 引擎（V8）也有同款——JIT + 逃逸分析 + 内联缓存。Java 和 JS 的&quot;快&quot;殊途同归：都是&quot;热点代码编译成机器码 + 对象生命周期优化&quot;。</p><h2 id="垃圾回收-gc" tabindex="-1">垃圾回收（GC） <a class="header-anchor" href="#垃圾回收-gc" aria-label="Permalink to &quot;垃圾回收（GC）&quot;">​</a></h2><h3 id="判断对象可回收" tabindex="-1">判断对象可回收 <a class="header-anchor" href="#判断对象可回收" aria-label="Permalink to &quot;判断对象可回收&quot;">​</a></h3><ul><li><strong>引用计数法</strong>（早期）：循环引用问题，已弃用</li><li><strong>可达性分析</strong>（现用）：从 GC Roots 出发遍历，不可达即垃圾。GC Roots 包括：栈帧局部变量、静态变量、JNI 引用、活跃线程</li></ul><h3 id="回收算法" tabindex="-1">回收算法 <a class="header-anchor" href="#回收算法" aria-label="Permalink to &quot;回收算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>思路</th><th>缺点</th></tr></thead><tbody><tr><td><strong>标记-清除</strong></td><td>标记垃圾后直接清除</td><td>内存碎片</td></tr><tr><td><strong>标记-复制</strong></td><td>存活对象复制到另一半区域</td><td>浪费一半空间；适合&quot;存活少&quot;（新生代）</td></tr><tr><td><strong>标记-整理</strong></td><td>存活对象移到一端，清掉其余</td><td>移动成本高；适合&quot;存活多&quot;（老年代）</td></tr></tbody></table><h3 id="分代收集" tabindex="-1">分代收集 <a class="header-anchor" href="#分代收集" aria-label="Permalink to &quot;分代收集&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新生代（复制算法，Minor GC 频繁）</span></span>
<span class="line"><span>├── Eden（新对象）</span></span>
<span class="line"><span>└── Survivor S0 / S1（幸存者，年龄 +1，15 岁进老年代）</span></span>
<span class="line"><span>老年代（标记-整理/标记-清除，Major GC）</span></span></code></pre></div><p><strong>为什么分代</strong>：绝大多数对象朝生夕灭（如方法里的临时对象），新生代用复制算法性价比最高。</p><h3 id="常见收集器-面试答-g1-即可" tabindex="-1">常见收集器（面试答 G1 即可） <a class="header-anchor" href="#常见收集器-面试答-g1-即可" aria-label="Permalink to &quot;常见收集器（面试答 G1 即可）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>收集器</th><th>特点</th></tr></thead><tbody><tr><td><strong>G1</strong>（JDK 9+ 默认）</td><td>分 Region 管理堆，可预测停顿时间（<code>-XX:MaxGCPauseMillis</code>），JDK 17 默认</td></tr><tr><td>ZGC</td><td>JDK 15+，超低停顿（毫秒级），适合超大堆</td></tr><tr><td>CMS</td><td>老牌并发收集器，已废弃（JDK 14+ 移除）</td></tr></tbody></table><p>G1 一句话：<strong>把堆分成多个 Region，优先回收垃圾最多的 Region</strong>（Garbage First 名字由来）。</p><h2 id="类加载机制" tabindex="-1">类加载机制 <a class="header-anchor" href="#类加载机制" aria-label="Permalink to &quot;类加载机制&quot;">​</a></h2><h3 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加载 → 验证 → 准备 → 解析 → 初始化 → 使用 → 卸载</span></span></code></pre></div><ul><li><strong>加载</strong>：读 .class 文件生成 Class 对象</li><li><strong>验证</strong>：字节码安全校验</li><li><strong>准备</strong>：静态变量赋默认值（0 / null）</li><li><strong>解析</strong>：符号引用 → 直接引用</li><li><strong>初始化</strong>：执行静态代码块、静态变量赋真实值</li></ul><h3 id="双亲委派模型-必考" tabindex="-1">双亲委派模型（必考） <a class="header-anchor" href="#双亲委派模型-必考" aria-label="Permalink to &quot;双亲委派模型（必考）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动类加载器 Bootstrap（rt.jar，JDK 核心类）</span></span>
<span class="line"><span>  ↑ 委托</span></span>
<span class="line"><span>扩展类加载器 Platform（JDK 扩展类）</span></span>
<span class="line"><span>  ↑ 委托</span></span>
<span class="line"><span>应用类加载器 App（classpath 下的类）</span></span></code></pre></div><p><strong>流程</strong>：类加载请求 → 先问父加载器能不能加载 → 父都不行才自己加载。</p><p><strong>为什么这样设计</strong>：保证核心类安全——你的代码无法覆盖 <code>java.lang.String</code>，避免污染 JDK 核心类（核心类始终由 Bootstrap 加载）。</p><p><strong>打破双亲委派</strong>：SPI（JDBC 等）用线程上下文类加载器，Tomcat 也打破了（每个应用隔离）。</p><h2 id="jvm-调优与排查-面试基础" tabindex="-1">JVM 调优与排查（面试基础） <a class="header-anchor" href="#jvm-调优与排查-面试基础" aria-label="Permalink to &quot;JVM 调优与排查（面试基础）&quot;">​</a></h2><p>常用参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xms256m -Xmx256m        # 堆初始/最大（生产建议相等，避免扩容抖动）</span></span>
<span class="line"><span>-Xss512k                 # 每个线程栈大小</span></span>
<span class="line"><span>-XX:MaxMetaspaceSize     # 元空间上限</span></span>
<span class="line"><span>-XX:+HeapDumpOnOutOfMemoryError   # OOM 时自动 dump</span></span></code></pre></div><p>排查命令（详见 <a href="/knowledge/service/troubleshooting.html">线上问题排查</a>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jps       # 查看 Java 进程</span></span>
<span class="line"><span>jstack    # 线程栈（查死锁、线程状态）</span></span>
<span class="line"><span>jmap      # 堆快照（查 OOM 对象）</span></span>
<span class="line"><span>jstat     # 查看 GC 频率与耗时</span></span></code></pre></div><h3 id="gc-日志怎么读-调优的基本功" tabindex="-1">GC 日志怎么读（调优的基本功） <a class="header-anchor" href="#gc-日志怎么读-调优的基本功" aria-label="Permalink to &quot;GC 日志怎么读（调优的基本功）&quot;">​</a></h3><p>生产环境开 GC 日志（JDK 9+ 语法见《Java 服务部署》），一次 Minor GC 长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2026-10-13T11:00:02.123+0800][info][gc] GC(42) Pause Young (Normal) (G1 Evacuation Pause)</span></span>
<span class="line"><span>  GC(42) Eden regions: 24-&gt;0(32)</span></span>
<span class="line"><span>  GC(42) Survivor regions: 2-&gt;3(4)</span></span>
<span class="line"><span>  GC(42) Pause Young (Normal) 38M-&gt;12M(256M) 8.512ms</span></span></code></pre></div><p>抓三个数就够：</p><table tabindex="0"><thead><tr><th>看什么</th><th>健康值</th><th>异常信号</th></tr></thead><tbody><tr><td><strong>停顿时间</strong>（Pause ... 8.512ms）</td><td>&lt; 200ms</td><td>频繁超 1s → 停顿敏感业务不可接受</td></tr><tr><td><strong>GC 频率</strong>（GC(42) 编号涨得快）</td><td>Minor GC 分钟级</td><td>秒级一次 → 分配速率过高或堆太小</td></tr><tr><td><strong>GC 后堆占用</strong>（38M→12M）</td><td>回落后保持平稳</td><td>每次 GC 后水位持续抬高 → <strong>有泄漏趋势</strong></td></tr></tbody></table><p><strong>最常见的调优动作</strong>（面试常考&quot;你怎么调 JVM&quot;）：不是改算法，是<strong>改堆大小和 GC 器</strong>——<code>-Xms=-Xmx</code>（消除伸缩抖动）→ 堆给到物理内存的 60~70%（留 30% 给堆外）→ 仍停顿超标的低延迟业务换 ZGC。</p><h3 id="oom-内存泄漏排查三步法" tabindex="-1">OOM / 内存泄漏排查三步法 <a class="header-anchor" href="#oom-内存泄漏排查三步法" aria-label="Permalink to &quot;OOM / 内存泄漏排查三步法&quot;">​</a></h3><p><strong>现象</strong>：<code>java.lang.OutOfMemoryError: Java heap space</code>（堆溢出）或更隐蔽的——进程内存天天涨、过几天被 OOMKilled。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 保留现场：-XX:+HeapDumpOnOutOfMemoryError 自动 dump（没配就 jmap -dump:live,format=b 手动抓）</span></span>
<span class="line"><span>② 分析 dump：用 MAT（Eclipse Memory Analyzer）或 IDEA 打开</span></span>
<span class="line"><span>   → 看 Dominator Tree：谁占了最大内存？</span></span>
<span class="line"><span>   → 看 Leak Suspects：MAT 自动报告的可疑泄漏点</span></span>
<span class="line"><span>③ 定位代码：典型嫌疑人——</span></span>
<span class="line"><span>   · static 集合只加不减（&quot;缓存&quot;越攒越大）</span></span>
<span class="line"><span>   · ThreadLocal 没 remove（线程池复用场景，见《Java 并发》）</span></span>
<span class="line"><span>   · 连接/流没关（try-with-resources 没包住）</span></span>
<span class="line"><span>   · 大对象进缓存（一次把整个表 load 进 Map）</span></span></code></pre></div><p><strong>排查顺序的黄金法则</strong>：先看&quot;对象数量是不是异常多&quot;（代码 bug 加了不该加的），再看&quot;单个对象是不是异常大&quot;（一次加载太多数据），别一上来就调堆——堆调大只是让&quot;到达 OOM 的时间变长&quot;，不治病。</p><h2 id="面试题速查" tabindex="-1">面试题速查 <a class="header-anchor" href="#面试题速查" aria-label="Permalink to &quot;面试题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>堆和栈的区别</td><td>堆存对象（共享）、栈存调用帧（私有）；堆要 GC、栈随方法退出自动释放</td></tr><tr><td>什么是 OOM</td><td>堆/元空间/直接内存耗尽的 <code>OutOfMemoryError</code></td></tr><tr><td>什么是 StackOverflow</td><td>栈深度超限，递归没出口</td></tr><tr><td>GC 判断对象死亡的算法</td><td>可达性分析（GC Roots）</td></tr><tr><td>新生代为什么用复制算法</td><td>存活少，复制成本低、无碎片</td></tr><tr><td>G1 和 CMS 区别</td><td>G1 分 Region、可预测停顿；CMS 已废弃</td></tr><tr><td>双亲委派是什么</td><td>子加载器先委托父加载器，保证核心类不被覆盖</td></tr><tr><td>什么时候触发 Full GC</td><td>老年代空间不足、元空间不足、System.gc()</td></tr><tr><td>什么是 JIT</td><td>热点代码运行时编译成机器码，分层编译 C1→C2</td></tr><tr><td>逃逸分析能做什么优化</td><td>栈上分配、标量替换、锁消除——对象不逃出方法就免 GC</td></tr><tr><td>怎么判断 GC 健康</td><td>看停顿时间、GC 频率、GC 后水位是否持续抬高</td></tr><tr><td>OOM 排查三步</td><td>dump 现场（HeapDumpOnOutOfMemoryError）→ MAT 分析 Dominator Tree → 查代码嫌疑人（static 集合/ThreadLocal/未关流）</td></tr><tr><td>调优第一步做什么</td><td>统一 -Xms=-Xmx 消除伸缩抖动，再考虑堆大小和 GC 器选择</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/java/java-concurrency.html">Java 并发编程</a> - JMM 与线程</li><li><a href="/knowledge/service/troubleshooting.html">线上问题排查</a> - jstack/jmap 实战</li><li><a href="/knowledge/service/java/java-basics.html">Java 入门（JS 开发者视角）</a> - 语言基础</li><li><a href="/knowledge/service/java/java-deployment.html">Java 服务部署最佳实践</a> - 生产 JVM 参数模板（-Xms/-Xmx/GC 日志/G1/ZGC）</li><li><a href="/knowledge/service/java/java-high-concurrency.html">Java（Spring Boot）高并发与高可用设计</a> - 容量视角的 JVM 调优</li></ul>`,58)])])}const u=t(i,[["render",p]]);export{g as __pageData,u as default};
